def rows_of_csv(response):
 assert response.status==200 and 'text/csv' in response.headers.get('content-type',''),response.text()[:200]
 return list(csv.reader(io.StringIO(response.body().decode('utf-8-sig'))))
def data_rows(response):return [r for r in rows_of_csv(response) if r and re.fullmatch(r'[1-9][0-9]*',r[0])]
